const savedLanguage =
  localStorage.getItem("shoufbayt_language") ||
  localStorage.getItem("smartestate_language") ||
  "en";

const updateHtmlLanguage = (language) => {
  document.documentElement.lang = language;
  document.documentElement.dir = language === "ar" ? "rtl" : "ltr";
};

i18n.use(initReactI18next).init({
  resources,
  lng: savedLanguage,
  fallbackLng: "en",
  interpolation: {
    escapeValue: false,
  },
});

updateHtmlLanguage(savedLanguage);

i18n.on("languageChanged", (language) => {
  localStorage.setItem("shoufbayt_language", language);
  updateHtmlLanguage(language);
});

export default i18n;
